// src/services/firebase/firebaseService.ts
import { initializeApp, FirebaseApp } from 'firebase/app';
import {
  getAuth,
  signInAnonymously,
  onAuthStateChanged as firebaseOnAuthStateChanged,
  deleteUser,
  updateProfile,
  Auth,
  User,
  NextOrObserver
} from 'firebase/auth';
import {
  getFirestore,
  doc,
  setDoc,
  getDoc,
  deleteDoc,
  updateDoc,
  Firestore,
} from 'firebase/firestore';
import {
  ref as rtdbRef,
  get as rtdbGet,
  child as rtdbChild,
  push as rtdbPush,
  onValue as rtdbOnValue,
  onChildAdded as rtdbOnChildAdded,
  onChildRemoved as rtdbOnChildRemoved,
  getDatabase,
  remove as rtdbRemove,
  set as rtdbSet,
  onDisconnect,
  Database,
  DataSnapshot
} from 'firebase/database';
import {
  deleteObject,
  getDownloadURL,
  uploadBytesResumable,
  getStorage,
  listAll,
  ref as storageRef,
  FirebaseStorage,
  UploadTaskSnapshot
} from 'firebase/storage';

const firebaseConfig = {
  // @ts-ignore
  apiKey: import.meta.env.VITE_API_KEY || '',
  // @ts-ignore
  authDomain: import.meta.env.VITE_AUTH_DOMAIN || '',
  // @ts-ignore
  projectId: import.meta.env.VITE_PROJECT_ID || '',
  // @ts-ignore
  storageBucket: import.meta.env.VITE_STORAGE_BUCKET || '',
  // @ts-ignore
  messagingSenderId: import.meta.env.VITE_MESSAGING_SENDER_ID || '',
  // @ts-ignore
  appId: import.meta.env.VITE_APP_ID || '',
  // @ts-ignore
  measurementId: import.meta.env.VITE_MEASUREMENT_ID || '',
};

export interface MessageData {
  message: string;
  id: string;
  username: string;
  time: string;
  download?: string | null;
  roomId?: string;
  user?: boolean;
}

export interface UserData {
  username: string;
  id: string;
}

interface RoomListeners {
  onMemberJoined?: (user: UserData) => void;
  onMemberLeft?: (user: UserData) => void;
  onKick?: (user: UserData) => void;
}

interface ScreenSignalingListeners {
  onNewUser?: (peerId: string) => void;
  onCall?: (data: { username: string; timestamp: number }) => void;
  onStopCall?: () => void;
}

class Firebase {
  static instance: Firebase | null = null;
  auth: Auth;
  db: Firestore;
  database: Database;
  storage: FirebaseStorage;

  constructor() {
    if (!Firebase.instance) {
      const app = initializeApp(firebaseConfig);
      this.auth = getAuth(app);
      this.db = getFirestore(app);
      this.database = getDatabase(app);
      this.storage = getStorage(app);
      Firebase.instance = this;
    }
    // Singleton assignment in JS logic, here we assign to keep TS happy but it relies on static instance
    const instance = Firebase.instance as Firebase;
    this.auth = instance.auth;
    this.db = instance.db;
    this.database = instance.database;
    this.storage = instance.storage;
    return instance;
  }

  getCurrentUser(): User | null {
    return this.auth?.currentUser || null;
  }

  getCurrentUserId(): string | null {
    return this.getCurrentUser()?.uid || null;
  }

  async safeUpdateDisplayName(name: string): Promise<boolean> {
    try {
      const user = this.getCurrentUser();
      if (!user || !name) return false;
      await updateProfile(user, { displayName: name });
      return true;
    } catch (e) {
      console.warn('safeUpdateDisplayName failed', e);
      return false;
    }
  }

  async login({ room_id, username, isOwner }: { room_id: string; username: string; isOwner: boolean }): Promise<boolean> {
    if (!room_id || !username) return false;

    try {
      const roomRef = doc(this.db, 'rooms', room_id);
      const snapDoc = await getDoc(roomRef);

      if (isOwner && !snapDoc.exists()) {
        await signInAnonymously(this.auth);
        const uid = this.getCurrentUserId();
        if (!uid) return false;

        await setDoc(roomRef, {
          username,
          id: uid,
          participants: [username],
          isOpen: false,
        });

        await rtdbSet(rtdbRef(this.database, `${room_id}/users/${uid}`), {
          username,
          id: uid,
        });

        await this.safeUpdateDisplayName(username);
        return true;
      }

      if (snapDoc.exists() && snapDoc.data()?.isOpen) {
        await signInAnonymously(this.auth);
        const uid = this.getCurrentUserId();
        if (!uid) return false;

        await rtdbSet(rtdbRef(this.database, `${room_id}/users/${uid}`), {
          username,
          id: uid,
        });

        await this.safeUpdateDisplayName(username);
        return true;
      }
    } catch (error) {
      console.error('login error:', error);
      return false;
    }
    return false;
  }

  async validateRoomId(room_id: string): Promise<boolean> {
    if (!room_id) return false;
    try {
      const [dbSnap, rtdbSnap] = await Promise.all([
        getDoc(doc(this.db, 'rooms', room_id)),
        rtdbGet(rtdbChild(rtdbRef(this.database), room_id)),
      ]);
      return !!dbSnap.exists() && !!rtdbSnap.exists();
    } catch (e) {
      console.error('validateRoomId error:', e);
      return false;
    }
  }

  async validateUserSession(room_id: string, id: string | null = null): Promise<boolean> {
    const uid = id || this.getCurrentUserId();
    if (!room_id || !uid) return false;
    try {
      const userSnap = await rtdbGet(rtdbRef(this.database, `${room_id}/users/${uid}`));
      if (!userSnap.exists() && this.getCurrentUser()) {
        try {
          // Check if current user object exists before deleting
          const currentUser = this.getCurrentUser();
          if (currentUser) {
            await deleteUser(currentUser);
          }
        } catch (e) {
          console.warn('deleteUser failed in validateUserSession', e);
        }
        return false;
      }
      return true;
    } catch (e) {
      console.error('validateUserSession error:', e);
      return false;
    }
  }

  async checkUsernameAvailability(room_id: string, username: string): Promise<boolean> {
    if (!room_id || !username) return false;
    try {
      const snapshot = await rtdbGet(rtdbChild(rtdbRef(this.database), `${room_id}/users`));
      if (!snapshot.exists()) return true;

      let available = true;
      snapshot.forEach((userSnap) => {
        const u = userSnap.val() as UserData;
        if (!u) return;
        if (u.username === username) {
          available = u.id === this.getCurrentUserId();
          return true;
        }
      });
      return available;
    } catch (e) {
      console.error('checkUsernameAvailability error:', e);
      return false;
    }
  }

  async createRoomTransaction(username: string): Promise<string | null> {
    if (!username) return null;
    try {
      const newRoomRef = rtdbPush(rtdbChild(rtdbRef(this.database), 'rooms'));
      const roomId = newRoomRef.key;
      if (!roomId) return null;

      const success = await this.login({ room_id: roomId, username, isOwner: true });
      return success ? roomId : null;
    } catch (e) {
      console.error("createRoomTransaction error", e);
      return null;
    }
  }

  async sendAiMessage({ message, id, username, roomId, time }: MessageData): Promise<boolean> {
    if (!message || !roomId) return false;
    try {
      await rtdbPush(rtdbChild(rtdbRef(this.database), `${roomId}/ai-messages`), {
        message,
        id,
        username,
        time,
        user: true
      });
      return true;
    } catch (e) {
      console.error('sendAiMessage error:', e);
      return false;
    }
  }

  async logout({ room_id, isOwner }: { room_id: string; isOwner: boolean }): Promise<void> {
    const uid = this.getCurrentUserId();
    if (!room_id || !uid) return;

    try {
      const roomDoc = await getDoc(doc(this.db, 'rooms', room_id));
      const userSnap = await rtdbGet(rtdbChild(rtdbRef(this.database), `${room_id}/users/${uid}`));

      if (!roomDoc.exists() && !userSnap.exists()) {
        try {
          const u = this.getCurrentUser();
          if (u) await deleteUser(u);
        } catch (e) {
          console.warn('deleteUser failed (maybe needs recent auth)', e);
        }
        return;
      }

      const currentUser = this.getCurrentUser();

      if (isOwner) {
        await Promise.allSettled([
          deleteDoc(doc(this.db, 'rooms', room_id)).catch((e) => console.warn('deleteDoc failed', e)),
          rtdbRemove(rtdbRef(this.database, room_id)).catch((e) => console.warn('rtdbRemove failed', e)),
          this.deleteFiles(room_id).catch((e) => console.warn('deleteFiles failed', e)),
          (async () => {
            try {
              if (currentUser) await deleteUser(currentUser);
            } catch (e) {
              console.warn('deleteUser failed (owner logout)', e);
            }
          })(),
        ]);
        return;
      }

      await Promise.allSettled([
        rtdbRemove(rtdbRef(this.database, `${room_id}/users/${uid}`)).catch((e) => console.warn('rtdbRemove user failed', e)),
        (async () => {
          try {
            if (currentUser) await deleteUser(currentUser);
          } catch (e) {
            console.warn('deleteUser failed (non-owner logout)', e);
          }
        })(),
      ]);
    } catch (error) {
      console.error('logout error:', error);
    }
  }

  async allowParticipants(room_id: string, callback: ((isOpen: boolean) => void) | undefined, allow: boolean): Promise<boolean> {
    if (!room_id) return false;
    try {
      const snapShot = await getDoc(doc(this.db, 'rooms', room_id));
      if (!snapShot.exists()) return false;

      const uid = this.getCurrentUserId();
      if (uid && uid === snapShot.data()?.id) {
        const newIsOpen = !allow;
        await updateDoc(doc(this.db, 'rooms', room_id), { isOpen: newIsOpen });
        try {
          callback?.(newIsOpen);
        } catch (e) {
          console.warn('allowParticipants callback error', e);
        }
        return true;
      }
    } catch (e) {
      console.error('allowParticipants error:', e);
    }
    return false;
  }

  async isOwnerLogout(room_id: string): Promise<boolean> {
    if (!room_id) return false;
    const uid = this.getCurrentUserId();
    if (!uid) return false;

    try {
      const roomRef = doc(this.db, 'rooms', room_id);
      const docSnap = await getDoc(roomRef);

      if (docSnap.exists()) {
        if (docSnap.data()?.id === uid) {
          await this.logout({ room_id, isOwner: true });
          return true;
        } else {
          await this.logout({ room_id, isOwner: false });
          return false;
        }
      }

      try {
        const u = this.getCurrentUser();
        if (u) await deleteUser(u);
      } catch (e) {
        console.warn('deleteUser failed in isOwnerLogout', e);
      }
      return false;
    } catch (e) {
      console.error('isOwnerLogout error:', e);
      return false;
    }
  }

  async getRoomOwner(room_id: string): Promise<string> {
    if (!room_id) return '';
    try {
      const docSnap = await getDoc(doc(this.db, 'rooms', room_id));
      return docSnap.exists() ? docSnap.data()?.username || '' : '';
    } catch (e) {
      console.error('getRoomOwner error:', e);
      return '';
    }
  }

  async getCurrentUserDetails(room_id: string): Promise<string> {
    const uid = this.getCurrentUserId();
    if (!room_id || !uid) return '';
    try {
      const result = await rtdbGet(rtdbRef(this.database, `${room_id}/users/${uid}`));
      return result.exists() ? result.val()?.username || '' : '';
    } catch (e) {
      console.error('getCurrentUserDetails error:', e);
      return '';
    }
  }

  async isOwner(room_id: string): Promise<boolean> {
    const uid = this.getCurrentUserId();
    if (!room_id || !uid) return false;
    try {
      const docSnap = await getDoc(doc(this.db, 'rooms', room_id));
      return docSnap.exists() && docSnap.data()?.id === uid;
    } catch (e) {
      console.error('isOwner error:', e);
      return false;
    }
  }

  onValueChange(room_id: string, callback: (id: string) => void): void {
    const id = this.getCurrentUserId();
    if (!id || !room_id) return;

    try {
      rtdbOnValue(
        rtdbRef(this.database, `${room_id}/users/${id}`),
        (snapShot) => {
          const username = snapShot.val()?.username;
          if (!username) {
            try {
              callback?.(id);
            } catch (e) {
              console.warn('onValueChange callback failed', e);
            }
          }
        },
        { onlyOnce: true }
      );
    } catch (e) {
      console.error('onValueChange error:', e);
    }
  }

  async removeParticipant(room_id: string, id: string): Promise<boolean> {
    if (!room_id || !id) return false;
    try {
      if (!(await this.isOwner(room_id))) return false;

      const docSnap = await getDoc(doc(this.db, 'rooms', room_id));
      const userSnap = await rtdbGet(rtdbChild(rtdbRef(this.database), `${room_id}/users/${id}`));
      if (!docSnap.exists() || !userSnap.exists()) return false;

      await rtdbRemove(rtdbRef(this.database, `${room_id}/users/${id}`));
      return true;
    } catch (e) {
      console.error('removeParticipant error:', e);
      return false;
    }
  }

  setupPresence(room_id: string, user_id: string | null): void {
    if (!room_id || !user_id) return;
    try {
      const userStatusRef = rtdbRef(this.database, `${room_id}/users/${user_id}`);
      const onDisconnectRef = onDisconnect(userStatusRef);
      onDisconnectRef.remove().catch((err) => {
        console.warn('Failed to attach onDisconnect listener', err);
      });
    } catch (e) {
      console.error('setupPresence error:', e);
    }
  }

  subscribeToMessages(room_id: string, callback: (msg: MessageData) => void): () => void {
    if (!room_id || !callback) return () => { };

    const messagesRef = rtdbChild(rtdbRef(this.database), `${room_id}/messages`);
    const unsubscribe = rtdbOnChildAdded(messagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        callback(data);
      }
    });
    return unsubscribe;
  }

  subscribeToRoomUsers(room_id: string, { onMemberJoined, onMemberLeft, onKick }: RoomListeners = {}): () => void {
    if (!room_id) return () => { };
    const usersRef = rtdbChild(rtdbRef(this.database), `${room_id}/users`);

    const unsubAdded = rtdbOnChildAdded(usersRef, (snapshot) => {
      const val = snapshot.val();
      if (val && onMemberJoined) onMemberJoined(val);
    });

    const unsubRemoved = rtdbOnChildRemoved(usersRef, (snapshot) => {
      const val = snapshot.val();
      if (val) {
        if (onMemberLeft) onMemberLeft(val);
        if (onKick) onKick(val);
      }
    });

    return () => {
      unsubAdded();
      unsubRemoved();
    };
  }

  async sendMessage({ message, id, username, roomId, time, download = null }: MessageData): Promise<boolean> {
    if (!message || !id || !username || !roomId || !time) return false;
    if (this.getCurrentUserId() !== id) return false;
    try {
      const messages = { message, id, username, time, download };
      await rtdbPush(rtdbChild(rtdbRef(this.database), `${roomId}/messages`), messages);
      return true;
    } catch (e) {
      console.error('sendMessage error:', e);
      return false;
    }
  }

  subscribeToAIMessages(room_id: string, callback: (msg: MessageData) => void): () => void {
    if (!room_id || !callback) return () => { };
    const aiRef = rtdbChild(rtdbRef(this.database), `${room_id}/ai-messages`);
    return rtdbOnChildAdded(aiRef, (snapshot) => {
      const data = snapshot.val();
      if (data) callback(data);
    });
  }

  async getMembers(room_id: string, callbackMember: (list: UserData[]) => void): Promise<void> {
    if (!room_id || typeof callbackMember !== 'function') return;
    try {
      const res = await rtdbGet(rtdbChild(rtdbRef(this.database), `${room_id}/users`));
      if (!res.exists()) return;
      const list: UserData[] = [];
      res.forEach((snap) => {
        const { username, id } = snap.val() || {};
        if (username && id) list.push({ username, id });
      });
      callbackMember(list);
    } catch (error) {
      console.error('getMembers error:', error);
    }
  }

  sendFile(
    sender: string,
    filename: string,
    content: ArrayBuffer | Uint8Array | Blob,
    room_id: string,
    time: string,
    callback: (url: string) => void,
    onProgress?: (progress: { loaded: number; total: number; lengthComputable: boolean; progress: number }) => void
  ): boolean {
    if (!sender || !filename || !content || !room_id || !time) return false;
    try {
      let fileContent = content;
      if (content instanceof ArrayBuffer) {
        fileContent = new Uint8Array(content);
      } else if (ArrayBuffer.isView(content)) {
        fileContent = new Uint8Array(content.buffer);
      }

      const fileRef = storageRef(this.storage, `${room_id}/${time} time:${filename}`);
      const uploadTask = uploadBytesResumable(fileRef, fileContent as Uint8Array | Blob);

      uploadTask.on(
        'state_changed',
        (snapshot: UploadTaskSnapshot) => {
          const progress = (snapshot.bytesTransferred / (snapshot.totalBytes || 1)) * 100;
          onProgress?.({
            loaded: snapshot.bytesTransferred,
            total: snapshot.totalBytes,
            lengthComputable: !!snapshot.totalBytes,
            progress,
          });
        },
        (error) => {
          console.error('upload error:', error);
        },
        async () => {
          try {
            const url = await getDownloadURL(uploadTask.snapshot.ref);
            try {
              callback?.(url);
            } catch (e) {
              console.warn('sendFile callback failed', e);
            }
          } catch (e) {
            console.error('getDownloadURL failed', e);
          }
        }
      );
      return true;
    } catch (e) {
      console.error('sendFile error:', e);
      return false;
    }
  }

  async getMediaFiles(room_id: string, callback: ((list: any[]) => void), setIsLoading?: (loading: boolean) => void): Promise<void> {
    if (!room_id) {
      setIsLoading?.(false);
      return;
    }
    try {
      setIsLoading?.(true);
      const res = await listAll(storageRef(this.storage, room_id));
      if (!res || !res.items || res.items.length === 0) {
        callback?.([]);
        setIsLoading?.(false);
        return;
      }
      const promises = res.items.map((item) =>
        getDownloadURL(storageRef(this.storage, item.fullPath))
          .then((url) => ({ filename: item.name, downloadUrl: url }))
          .catch((err) => {
            console.warn(`Failed to get URL for ${item.name}:`, err);
            return null;
          })
      );
      const results = await Promise.allSettled(promises);
      const list = results
        .filter((r): r is PromiseFulfilledResult<any> => r.status === 'fulfilled' && !!r.value)
        .map((r) => r.value);

      callback?.(list);
    } catch (e) {
      console.error('getMediaFiles error:', e);
      callback?.([]);
    } finally {
      setIsLoading?.(false);
    }
  }

  async getFileCount(room_id: string): Promise<number> {
    if (!room_id) return 0;
    try {
      const res = await listAll(storageRef(this.storage, room_id));
      return res?.items?.length || 0;
    } catch (e) {
      console.error('getFileCount error:', e);
      return 0;
    }
  }

  async deleteFiles(room_id: string): Promise<boolean> {
    if (!room_id) return false;
    try {
      const res = await listAll(storageRef(this.storage, room_id));
      if (!res?.items || res.items.length === 0) return true;
      await Promise.allSettled(
        res.items.map((item) => deleteObject(storageRef(this.storage, item.fullPath)).catch((err) => {
          console.warn('deleteObject failed for', item.fullPath, err);
        }))
      );
      return true;
    } catch (e) {
      console.error('deleteFiles error:', e);
      return false;
    }
  }

  onAuthStateChanged(callback: NextOrObserver<User>): void {
    try {
      firebaseOnAuthStateChanged(this.auth, callback);
    } catch (e) {
      console.error('onAuthStateChanged error:', e);
    }
  }

  async joinScreenShare(roomId: string, peerId: string): Promise<void> {
    if (!roomId || !peerId) return;
    try {
      await rtdbSet(rtdbRef(this.database, `${roomId}/screenshare/peers/${peerId}`), {
        id: peerId,
        timestamp: Date.now()
      });
    } catch (e) {
      console.error("joinScreenShare error", e);
    }
  }

  async announceCall(roomId: string, username: string): Promise<void> {
    if (!roomId || !username) return;
    try {
      await rtdbSet(rtdbRef(this.database, `${roomId}/screenshare/active_call`), {
        username,
        timestamp: Date.now()
      });
    } catch (e) {
      console.error("announceCall error", e);
    }
  }

  subscribeToScreenSignaling(roomId: string, { onNewUser, onCall, onStopCall }: ScreenSignalingListeners = {}): () => void {
    if (!roomId) return () => { };

    const peersRef = rtdbRef(this.database, `${roomId}/screenshare/peers`);
    const activeCallRef = rtdbRef(this.database, `${roomId}/screenshare/active_call`);

    const unsubPeers = rtdbOnChildAdded(peersRef, (snapshot) => {
      const val = snapshot.val();
      if (val && val.id && onNewUser) {
        onNewUser(val.id);
      }
    });

    const unsubCall = rtdbOnValue(activeCallRef, (snapshot) => {
      const val = snapshot.val();
      if (val && onCall) {
        onCall(val);
      } else if (!val && onStopCall) {
        onStopCall();
      }
    });

    return () => {
      unsubPeers();
      unsubCall();
    }
  }

  async stopCall(roomId: string): Promise<void> {
    if (!roomId) return;
    try {
      await rtdbRemove(rtdbRef(this.database, `${roomId}/screenshare/active_call`));
    } catch (e) {
      console.error("stopCall error", e);
    }
  }
}

export default Firebase;
