import React from 'react'

interface DisplayMsgProps {
  message: string;
  setMessage: React.Dispatch<React.SetStateAction<string>>;
}

const DisplayMsg: React.FC<DisplayMsgProps> = ({ message, setMessage }) => {

  if (setMessage) {
    setTimeout(() => setMessage(''), 3000);
  }

  return (
    <div className='text-red-400 bg-slate-100 w-full h-fit rounded-md flex px-2 p-1 justify-center items-center'>
      <h1>{message}</h1>
    </div>
  )
}

export default DisplayMsg
